; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: neogeo (SNK Neo Geo (68000)), starts in turbo mode
; ============================================================

			org 0

;## ntc_md_vectors ntc_ng_boot
; (the 68k backend requires this section be named ntc_md_vectors - it's the
;  generic "68k vectors + header + start" slot, named after the first 68k target)
; The 68000 vector table at 0, then the Neo Geo cart header / BIOS jump table.
; ;!!NG the real Neo Geo P-ROM header (the "NEO-GEO" marker, the USER and
; interrupt jump entries, the security/soft-DIP area) goes here - stubbed.
			dc.l $00100000          ; initial SSP (top of 68k work RAM) ;!!NG
			dc.l ntc_ng_boot        ; reset PC
			ds.l 62, 0              ; the rest of the 68000 vectors (IRQ, traps) ;!!NG wire VBlank
; ---- the cart header would follow here (ds to $100, the NEO-GEO marker ...) ;!!NG

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			move.l sp, ntc_ip
			movea.l ntc_csp, sp
			endm
NTC_TS		macro			; back to the thread
			movea.l ntc_ip, sp
			endm

ntc_start:
			move.l sp, ntc_csp		; the real stack (the library's jsr calls)
			lea main_thread, sp
			rts

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dc.l kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 13: Input "How many passes (Return = 5)"; passes
			dc.l kw_printstrvar, str0
			dc.l kw_inputint, var_passes

			; main.bas 14: If passes < 1 Or passes > 100 Then passes = 5
			dc.l kw_scpltvl, var_passes, 1
			dc.l kw_ftov, tmp0
			dc.l kw_scpgtvl, var_passes, 100
			dc.l kw_ftov, tmp1
			dc.l kw_orvv, tmp0, tmp1, tmp0
			dc.l kw_goto_ifzero, tmp0, if1_1
			dc.l kw_ltov, 5, var_passes
if1_1:

			; main.bas 15: Do
do2_t:

			; main.bas 16: Print
			dc.l kw_printnl

			; main.bas 17: Print "T = turbo, N = normal, X = exit"
			dc.l kw_printstrvar, str1
			dc.l kw_printnl

			; main.bas 18: Do : k = UCase$(Inkey$) : Frame : Loop Until (k = "T") Or (k = "N") Or (k = "X")
do3_t:
			dc.l kw_inkeys, stmp0
			dc.l kw_strucase, var_k, stmp0
			dc.l kw_frame
			dc.l kw_strcmpeq, var_k, str2
			dc.l kw_ftov, tmp0
			dc.l kw_strcmpeq, var_k, str3
			dc.l kw_ftov, tmp1
			dc.l kw_orvv, tmp0, tmp1, tmp0
			dc.l kw_strcmpeq, var_k, str4
			dc.l kw_ftov, tmp1
			dc.l kw_orvv, tmp0, tmp1, tmp0
			dc.l kw_goto_ifzero, tmp0, do3_t
do3_e:

			; main.bas 19: If k = "X" Then Exit Do
			dc.l kw_strcmpeq, var_k, str4
			dc.l kw_goto_iffalse, if4_1
			dc.l do2_e_go
if4_1:

			; main.bas 20: Print IIf(k = "T", "Turbo", "Normal"); ": "; passes; " passes..."
			dc.l kw_strcmpeq, var_k, str2
			dc.l kw_ftov, tmp0
			dc.l kw_goto_ifzero, tmp0, ch5_0
			dc.l kw_strcpy, stmp0, str5
			dc.l ch5_e_go
ch5_0:
			dc.l kw_strcpy, stmp0, str6
			dc.l ch5_e_go
ch5_1:
			dc.l kw_strcpy, stmp0, str7
ch5_e:
			dc.l kw_printstrvar, stmp0
			dc.l kw_printstrvar, str8
			dc.l kw_printint, var_passes
			dc.l kw_printstrvar, str9
			dc.l kw_printnl

			; main.bas 21: t0 = Ticks
			dc.l kw_ticks, tmp0
			dc.l kw_vtov, tmp0, var_t0

			; main.bas 22: If k = "T" Then
			dc.l kw_strcmpeq, var_k, str2
			dc.l kw_goto_iffalse, if6_1

			; main.bas 23: Turbo On

			; main.bas 24: RunPasses
			dc.l p_runpasses_c

			; main.bas 25: Turbo Off

			; main.bas 26: Else
			dc.l if6_e_go
if6_1:

			; main.bas 27: RunPasses
			dc.l p_runpasses_c

			; main.bas 28: End If
if6_e:

			; main.bas 29: t1 = Ticks
			dc.l kw_ticks, tmp0
			dc.l kw_vtov, tmp0, var_t1

			; main.bas 30: Print "Done - stop the stopwatch"
			dc.l kw_printstrvar, str10
			dc.l kw_printnl

			; main.bas 31: Print cnt; " primes below "; TOP
			dc.l kw_printint, var_cnt
			dc.l kw_printstrvar, str11
			dc.l kw_printnl

			; main.bas 32: If (k = "N") And (System.TicksPerSecond > 0) Then
			dc.l kw_strcmpeq, var_k, str3
			dc.l kw_ftov, tmp0
			dc.l kw_goto_ifzero, tmp0, if7_1

			; main.bas 33: Print "took "; t1 - t0; " ticks = "; (t1 - t0) \ System.TicksPerSecond; "."; ((t1 - t0) Mod System.TicksPerSecond) * 10 \ System.TicksPerSecond; " s"
			dc.l kw_subvv, var_t1, var_t0, tmp0
			dc.l kw_printstrvar, str12
			dc.l kw_printint, tmp0
			dc.l kw_subvv, var_t1, var_t0, tmp0
			dc.l kw_divvl, tmp0, 60, tmp0
			dc.l kw_printstrvar, str13
			dc.l kw_printint, tmp0
			dc.l kw_subvv, var_t1, var_t0, tmp0
			dc.l kw_modvl, tmp0, 60, tmp0
			dc.l kw_mulvl, tmp0, 10, tmp0
			dc.l kw_divvl, tmp0, 60, tmp0
			dc.l kw_printstrvar, str14
			dc.l kw_printint, tmp0
			dc.l kw_printstrvar, str15
			dc.l kw_printnl

			; main.bas 34: ElseIf k = "T" Then
			dc.l do2_t_go
if7_1:
			dc.l kw_strcmpeq, var_k, str2
			dc.l kw_goto_iffalse, do2_t

			; main.bas 35: Print "(turbo runs with interrupts off, so"
			dc.l kw_printstrvar, str16
			dc.l kw_printnl

			; main.bas 36: Print "time it with the stopwatch)"
			dc.l kw_printstrvar, str17
			dc.l kw_printnl

			; main.bas 37: End If
if7_2:
if7_e:

			; main.bas 38: Loop
			dc.l do2_t_go
do2_e:

			; main.bas 39: End
			dc.l kw_printnl0
			dc.l kw_printstrvar, str18
			dc.l kw_waitkey
			dc.l kw_stop

; ============================================================
; sub runpasses (turbo mode)
; ============================================================

p_runpasses:

			; main.bas 42: Dim p As Integer

			; main.bas 43: For p = 1 To passes
			dc.l kw_ltov, 1, var_runpasses_p
			dc.l kw_vtov, var_passes, for8_l
			dc.l kw_forupv, var_runpasses_p, for8_l, for8_e
for8_t:

			; main.bas 44: Sieve
			dc.l p_sieve_c

			; main.bas 45: Next
			dc.l kw_next1v, var_runpasses_p, for8_l, for8_t
for8_e:
			dc.l p_runpasses_r

; ============================================================
; sub sieve (turbo mode)
; ============================================================

p_sieve:

			; main.bas 49: Dim i As Integer, j As Integer

			; main.bas 50: For i = 2 To TOP
			dc.l kw_ltov, 2, var_sieve_i
for9_t:

			; main.bas 51: f(i) = 1
			dc.l kw_aset8, arr_f, var_sieve_i, lit_1

			; main.bas 52: Next
			dc.l kw_next1l, var_sieve_i, 8000, for9_t
for9_e:

			; main.bas 53: cnt = 0
			dc.l kw_ztov, var_cnt

			; main.bas 54: For i = 2 To TOP
			dc.l kw_ltov, 2, var_sieve_i
for10_t:

			; main.bas 55: If f(i) = 1 Then
			dc.l kw_aget8, arr_f, var_sieve_i, tmp0
			dc.l kw_cpeqvl, tmp0, 1
			dc.l kw_goto_iffalse, if11_1

			; main.bas 56: cnt = cnt + 1
			dc.l kw_inc, var_cnt

			; main.bas 57: j = i + i
			dc.l kw_add, var_sieve_i, var_sieve_i, var_sieve_j

			; main.bas 58: Do While j <= TOP
do12_t:
			dc.l kw_scplevl, var_sieve_j, 8000
			dc.l kw_goto_iffalse, do12_e

			; main.bas 59: f(j) = 0
			dc.l kw_aset8, arr_f, var_sieve_j, lit_0

			; main.bas 60: j = j + i
			dc.l kw_add, var_sieve_j, var_sieve_i, var_sieve_j

			; main.bas 61: Loop
			dc.l do12_t_go
do12_e:

			; main.bas 62: End If
if11_1:

			; main.bas 63: Next
			dc.l kw_next1l, var_sieve_i, 8000, for10_t
for10_e:
			dc.l p_sieve_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_e_go:			lea do2_e, sp
			rts
ch5_e_go:			lea ch5_e, sp
			rts
if6_e_go:			lea if6_e, sp
			rts
do2_t_go:			lea do2_t, sp
			rts
do12_t_go:			lea do12_t, sp
			rts

p_runpasses_c:		; call runpasses
			clr.w var_runpasses_p
			move.l sp, p_runpasses_rs
			lea p_runpasses, sp
			rts
p_runpasses_r:		; end of runpasses
			movea.l p_runpasses_rs, sp
			rts
p_sieve_c:		; call sieve
			clr.w var_sieve_i
			clr.w var_sieve_j
			move.l sp, p_sieve_rs
			lea p_sieve, sp
			rts
p_sieve_r:		; end of sieve
			movea.l p_sieve_rs, sp
			rts

; ============================================================
; Variables
; ============================================================

; (68000: in the RAM block at the end, from $FF8000)

; numbers passed by address (read only)
			even
ntc_aptab:		dc.l 0		; AddressOf: the procedures CallAddr runs, by number
lit_1:			dc.w 1
lit_0:			dc.w 0

; ============================================================
; Strings
; ============================================================

str0:			dc.b "How many passes (Return = 5)? ", 0
str1:			dc.b "T = turbo, N = normal, X = exit", 0
str2:			dc.b "T", 0
str3:			dc.b "N", 0
str4:			dc.b "X", 0
str5:			dc.b "Turbo", 0
str6:			dc.b "Normal", 0
str7:			dc.b 0
str8:			dc.b ": ", 0
str9:			dc.b " passes...", 0
str10:			dc.b "Done - stop the stopwatch", 0
str11:			dc.b " primes below 8000", 0
str12:			dc.b "took ", 0
str13:			dc.b " ticks = ", 0
str14:			dc.b ".", 0
str15:			dc.b " s", 0
str16:			dc.b "(turbo runs with interrupts off, so", 0
str17:			dc.b "time it with the stopwatch)", 0
str18:			dc.b "Press a key", 0
			even

; ============================================================
; Keyword library (used)
; ============================================================

			even
;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## ntc_d_inbuf @data

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			NTC_RS
			jsr ntc_plat_getkey
			NTC_TS
			rts

			even
;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			addq.l #4, sp
			rts
kw_gif_go:
			movea.l (sp), sp
			rts

			even
;## kw_goto_ifzero
;kw_goto_ifzero, <var>, <label>  - branch if var = 0
kw_goto_ifzero:
			movea.l (sp)+, a0
			tst.w (a0)
			beq kw_giz_go
			addq.l #4, sp
			rts
kw_giz_go:
			movea.l (sp), sp
			rts

			even
;## ntc_for_jump
; tails for the FOR / NEXT keywords: SP = thread at the label long
ntc_for_take:
			movea.l (sp), sp
			rts
ntc_for_skip:
			addq.l #4, sp
			rts

			even
;## kw_forupv ntc_for_jump
;kw_forupv, <var>, <limit var>, <endlabel>
kw_forupv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d1
			cmp.w (a0), d1
			blt ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_next1l ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit (past 32767: ends)
kw_next1l:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			addq.w #1, (a0)
			bvs ntc_for_skip
			cmp.w (a0), d1
			bge ntc_for_take		; limit >= var
			addq.l #4, sp
			rts

			even
;## kw_next1v ntc_for_jump
;kw_next1v, <var>, <limit var>, <toplabel>
kw_next1v:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			addq.w #1, (a0)
			bvs ntc_for_skip
			move.w (a1), d1
			cmp.w (a0), d1
			bge ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			move.l (sp)+, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), (a1)
			rts

			even
;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_ftov
;kw_ftov, <destvar>  - Z flag to var: true = -1, false = 0
kw_ftov:
			seq d0
			ext.w d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

; ============================================================
; Arithmetic (16 bit, wrapping)
; ============================================================

			even
;## kw_inc
kw_inc:
			movea.l (sp)+, a0
			addq.w #1, (a0)
			rts

			even
;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			add.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_subvv
;kw_subvv, <var1>, <var2>, <destvar>  - var1 - var2
kw_subvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			sub.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_mulvl
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			muls.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_div
; d0.w / d1.w signed, truncating: d0.w = quotient, d1.w = remainder (the
; dividend's sign). Divide by zero: quotient 0, remainder = dividend.
; -32768 / -1: quotient -32768, remainder 0 (as the Z80 library). jmp (a6)
ntc_div:
			tst.w d1
			beq ntc_div_z
			ext.l d0
			move.l d0, d2
			divs.w d1, d0
			bvs ntc_div_ov
			move.l d0, d1
			swap d1
			jmp (a6)
ntc_div_z:
			move.w d0, d1
			moveq #0, d0
			jmp (a6)
ntc_div_ov:
			move.w #$8000, d0
			moveq #0, d1
			jmp (a6)

			even
;## kw_divvv ntc_div
;kw_divvv, <var1>, <var2>, <destvar>  - var1 \ var2
kw_divvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			lea kw_div_q, a6
			bra ntc_div
kw_div_q:
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_divvl ntc_div kw_divvv
;kw_divvl, <var>, <literal>, <destvar>
kw_divvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			lea kw_div_q, a6
			bra ntc_div

			even
;## kw_modvv ntc_div
;kw_modvv, <var1>, <var2>, <destvar>  - var1 MOD var2
kw_modvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			lea kw_mod_r, a6
			bra ntc_div
kw_mod_r:
			movea.l (sp)+, a0
			move.w d1, (a0)
			rts

			even
;## kw_modvl ntc_div kw_modvv
kw_modvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			lea kw_mod_r, a6
			bra ntc_div

			even
;## kw_orvv
kw_orvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			or.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_cmp
; tails: d0 = a, d1 = b, test a <rel> b
ntc_cmp_slt:
			cmp.w d1, d0
			slt d0
			addq.b #1, d0
			rts
ntc_cmp_sle:
			cmp.w d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_cmp_sgt:
			cmp.w d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_cmp_sge:
			cmp.w d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_cmp_ult:
			cmp.w d1, d0
			scs d0
			addq.b #1, d0
			rts
ntc_cmp_ule:
			cmp.w d1, d0
			sls d0
			addq.b #1, d0
			rts
ntc_cmp_ugt:
			cmp.w d1, d0
			shi d0
			addq.b #1, d0
			rts
ntc_cmp_uge:
			cmp.w d1, d0
			scc d0
			addq.b #1, d0
			rts
ntc_cmp_eq:
			cmp.w d1, d0
			rts
ntc_cmp_ne:
			cmp.w d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_scpltvl ntc_cmp
kw_scpltvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_slt

			even
;## kw_scplevl ntc_cmp
kw_scplevl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_sle

			even
;## kw_scpgtvl ntc_cmp
kw_scpgtvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_sgt

			even
;## kw_cpeqvl
kw_cpeqvl:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			cmp.w (a0), d1
			rts

			even
;## kw_aget8
;kw_aget8, <arraybase>, <indexvar>, <destvar>  - Byte array element (0 .. 255)
kw_aget8:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			moveq #0, d1
			move.b 0(a0, d0.l), d1
			movea.l (sp)+, a1
			move.w d1, (a1)
			rts

			even
;## kw_aset8
;kw_aset8, <arraybase>, <indexvar>, <sourcevar>  - set a Byte array element (low byte)
kw_aset8:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			movea.l (sp)+, a1
			move.b 1(a1), 0(a0, d0.l)
			rts

			even
;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
ntc_strcpy_lp:					; a0 -> a1, at most d1 chars (d1.w > 0), then the 0
			subq.w #1, d1
			bmi ntc_strcpy_cut
ntc_strcpy_l2:
			move.b (a0)+, (a1)+
			dbeq d1, ntc_strcpy_l2
			beq ntc_strcpy_e
ntc_strcpy_cut:
			clr.b (a1)
ntc_strcpy_e:
			rts

			even
;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
kw_seq_lp:
			move.b (a0)+, d0
			cmp.b (a1)+, d0
			bne kw_seq_no
			tst.b d0
			bne kw_seq_lp
kw_seq_no:
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## ntc_gets ntc_data ntc_plat_screen ntc_plat_key
; line input with echo and backspace, on the real stack (jsr). a2 = buffer (its
; capacity in the byte before it). 0 terminated, then a new line.
ntc_gets:
			moveq #0, d3
			move.b -1(a2), d3			; capacity
			moveq #0, d4				; typed
ntc_gs_wait:
			jsr ntc_plat_getkey
			cmpi.b #13, d0
			beq ntc_gs_done
			cmpi.b #127, d0
			beq ntc_gs_del
			cmpi.b #8, d0
			beq ntc_gs_del
			cmpi.b #32, d0
			bcs ntc_gs_wait
			cmp.w d3, d4
			bcc ntc_gs_wait
			move.b d0, 0(a2, d4.w)
			addq.w #1, d4
			jsr ntc_plat_putc
			bra ntc_gs_wait
ntc_gs_del:
			tst.w d4
			beq ntc_gs_wait
			subq.w #1, d4
			jsr ntc_plat_backspace
			bra ntc_gs_wait
ntc_gs_done:
			clr.b 0(a2, d4.w)
			jmp ntc_plat_newline

			even
;## kw_inputint ntc_gets ntc_atoi ntc_d_inbuf
;kw_inputint, <var>  - signed decimal, stops at the first non digit
kw_inputint:
			move.l (sp)+, ntc_ivar
			lea ntc_inbuf, a2
			NTC_RS
			jsr ntc_gets
			NTC_TS
			lea ntc_inbuf, a0
			bra ntc_atoi

			even
;## ntc_atoi ntc_data
; text at a0 to a number into the var at (ntc_ivar). Spaces first, then - , then
; digits (or &H hex). Then rts (the thread).
ntc_atoi:
			moveq #0, d0				; value
			moveq #0, d2				; minus
ntc_at_sp:
			move.b (a0), d1
			cmpi.b #' ', d1
			bne ntc_at_sg
			addq.l #1, a0
			bra ntc_at_sp
ntc_at_sg:
			cmpi.b #'-', d1
			bne ntc_at_amp
			moveq #1, d2
			addq.l #1, a0
			move.b (a0), d1
ntc_at_amp:
			cmpi.b #'&', d1
			bne ntc_at_dec
			addq.l #1, a0
			move.b (a0)+, d1
			ori.b #$20, d1
			cmpi.b #'h', d1
			bne ntc_at_done
ntc_at_hex:
			moveq #0, d1
			move.b (a0)+, d1
			subi.b #'0', d1
			bcs ntc_at_done
			cmpi.b #10, d1
			bcs ntc_at_hd
			ori.b #$20, d1
			subi.b #'a'-'0', d1
			bcs ntc_at_done
			cmpi.b #6, d1
			bcc ntc_at_done
			addi.b #10, d1
ntc_at_hd:
			lsl.w #4, d0
			or.w d1, d0
			bra ntc_at_hex
ntc_at_dec:
			moveq #0, d1
			move.b (a0)+, d1
			subi.b #'0', d1
			bcs ntc_at_done
			cmpi.b #10, d1
			bcc ntc_at_done
			mulu.w #10, d0
			add.w d1, d0
			bra ntc_at_dec
ntc_at_done:
			tst.w d2
			beq ntc_at_st
			neg.w d0
ntc_at_st:
			movea.l ntc_ivar, a0
			move.w d0, (a0)
			rts

			even
;## kw_inkeys ntc_data ntc_plat_key
;kw_inkeys, <dest>  - Inkey$: the new key press as a string, "" if none
kw_inkeys:
			movea.l (sp)+, a2
			NTC_RS
			jsr ntc_plat_scankey
			NTC_TS
			move.b d0, (a2)+
			beq kw_iks_e
			clr.b (a2)
kw_iks_e:
			rts

			even
;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame (vertical blank)
kw_frame:
			NTC_RS
			jsr ntc_plat_frame
			NTC_TS
			rts

			even
;## kw_ticks ntc_data ntc_plat_ticks
;kw_ticks, <destvar>  - the tick count (frames, 60 or 50 a second)
kw_ticks:
			movea.l (sp)+, a2
			NTC_RS
			jsr ntc_plat_ticks
			NTC_TS
			move.w d0, (a2)
			rts

; ============================================================
; String functions. Numbers are passed as the address of a word.
; Results go to a string buffer. Dest may be the same as the source.
; ============================================================

			even
;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
kw_uc_lp:
			move.b (a0)+, d0
			cmpi.b #'a', d0
			bcs kw_uc_put
			cmpi.b #'z', d0
			bhi kw_uc_put
			subi.b #32, d0
kw_uc_put:
			move.b d0, (a1)+
			bne kw_uc_lp
			rts

			even
;## kw_bssinit ntc_data ntc_plat_screen
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  the RAM variables (not in the ROM). Check they fit under the end of RAM, then clear them.
;  Too big: a message, the program stops.
kw_bssinit:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			andi.l #$FFFF, d0
			move.l a0, d1
			add.l d0, d1
			cmpi.l #$01000000, d1
			bhi kw_bs_big
			tst.l d0
			beq kw_bs_e
kw_bs_lp:
			clr.b (a0)+
			subq.l #1, d0
			bne kw_bs_lp
kw_bs_e:
			rts
kw_bs_big:
			NTC_RS
			lea kw_bs_txt, a2
kw_bs_pl:
			moveq #0, d0
			move.b (a2)+, d0
			beq kw_bs_stop
			jsr ntc_plat_putc
			bra kw_bs_pl
kw_bs_stop:
			jsr ntc_plat_newline
			jmp kw_stop
kw_bs_txt:	dc.b "GURU 001", 0
			even

			even
;## ntc_ng_boot ntc_plat_data ntc_data ntc_plat_screen
ntc_ng_boot:
			move.w #$2700, sr          ; interrupts off during setup
			move.b d0, REG_DIPSW       ; kick the watchdog (any write)     ;!!NG value
			; clear the fix layer, set up the palette and a text font in fix tiles
			jsr ntc_ng_fixclear        ; (below)
			; hand control to the thread - the compiler's start code follows;
			; it sets A7 to the thread and runs. Interrupts get re-enabled there.
			; (ntc_plat_data / screen are pulled in as deps.)
			rts

			even
;## ntc_plat_data ntc_data
ntc_curx:   dc.w 0                     ; fix-layer cursor column (0..39)
ntc_cury:   dc.w 0                     ; row (0..31)
ntc_frames: dc.w 0                     ; frame counter (ntc_plat_ticks)

			even
;## ntc_plat_screen ntc_plat_data ntc_data
; the platform routines are entered with jsr and end with rts (real stack),
; keeping d2-d7 / a2-a6 (the 68k backend's convention).

; ntc_ng_fixaddr - d1.w = the VRAM word address of (ntc_curx, ntc_cury) in the
; fix map. The fix map is column-major: addr = NG_FIXMAP + col*32 + row.  ;!!NG layout
ntc_ng_fixaddr:
			move.w ntc_curx, d1
			lsl.w #5, d1               ; col * 32
			add.w ntc_cury, d1
			add.w #NG_FIXMAP, d1
			rts

; ntc_plat_putc - d0.b = character 32..126: write it as a fix tile, advance
ntc_plat_putc:
			jsr ntc_ng_fixaddr
			move.w d1, REG_VRAMADDR
			move.w #1, REG_VRAMMOD     ; (irrelevant for a single write)
			and.w #$00FF, d0
			; fix tile word = palette<<12 | char code ;!!NG tile numbering / font must be uploaded
			move.w d0, REG_VRAMRW
			addq.w #1, ntc_curx
			cmp.w #40, ntc_curx
			blt.s ntc_pc_done
			jsr ntc_plat_newline
ntc_pc_done:
			rts

; ntc_plat_newline - CR LF: column 0, next row (scroll not done yet) ;!!NG scroll
ntc_plat_newline:
			clr.w ntc_curx
			addq.w #1, ntc_cury
			cmp.w #32, ntc_cury
			blt.s ntc_nl_done
			move.w #31, ntc_cury
ntc_nl_done:
			rts

; ntc_ng_fixclear - blank the whole fix layer (space tile)   ;!!NG space tile index
ntc_ng_fixclear:
			move.w #NG_FIXMAP, REG_VRAMADDR
			move.w #1, REG_VRAMMOD
			move.w #40*32-1, d1
ntc_fc_lp:
			move.w #$0020, REG_VRAMRW
			dbra d1, ntc_fc_lp
			clr.w ntc_curx
			clr.w ntc_cury
			rts

			even
;## ntc_plat_backspace @unit ntc_plat_screen ntc_plat_data ntc_data
ntc_plat_backspace:
			tst.w ntc_curx
			beq.s ntc_bs_done
			subq.w #1, ntc_curx
			jsr ntc_ng_fixaddr
			move.w d1, REG_VRAMADDR
			move.w #$0020, REG_VRAMRW
ntc_bs_done:
			rts

			even
;## ntc_plat_key ntc_plat_data ntc_data
; ntc_plat_scankey - d0.b = a key or 0. Reads P1 (active low). Maps the stick
; to the CPC cursor codes and A/B/C to "A"/"B"/"C"; Start = 13.  ;!!NG bit map
ntc_plat_scankey:
			moveq #0, d0
			move.b REG_P1CNT, d1
			not.b d1                    ; active low -> 1 = pressed
			btst #4, d1                 ; A
			beq.s ntc_sk_b
			moveq #'A', d0
			rts
ntc_sk_b:
			btst #5, d1                 ; B
			beq.s ntc_sk_start
			moveq #'B', d0
			rts
ntc_sk_start:
			move.b REG_STATUS_B, d1
			not.b d1
			btst #0, d1                 ; Start P1
			beq.s ntc_sk_none
			moveq #13, d0
ntc_sk_none:
			rts

; ntc_plat_getkey - wait for a key
ntc_plat_getkey:
			jsr ntc_plat_scankey
			tst.b d0
			beq.s ntc_plat_getkey
			rts

			even
;## ntc_plat_frame ntc_plat_data ntc_data
; ntc_plat_frame - called once per NTC frame; bump the counter. A real build
; waits for VBlank here (the level-? interrupt) ;!!NG wire VBlank
ntc_plat_frame:
			addq.w #1, ntc_frames
			move.b d0, REG_DIPSW        ; kick the watchdog each frame   ;!!NG
			rts

			even
;## ntc_plat_ticks ntc_plat_data ntc_data
; ntc_plat_ticks - d0.w (Integer) = the frame counter (TicksPerSecond ~ 60)
ntc_plat_ticks:
			move.w ntc_frames, d0
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - a cart can't "exit"; spin (a real build returns to the BIOS
; menu / soft-resets) ;!!NG
ntc_plat_exit:
			bra.s ntc_plat_exit


			even
ntc_romend:			; the end of the ROM: the RAM block's first image follows
			org $FF8000
ntc_ram:
; variables
var_passes:			dc.w 0
			dc.b 40			; capacity
var_k:			ds.b 41
			even
var_t0:			dc.w 0
var_t1:			dc.w 0
var_cnt:			dc.w 0
p_runpasses_rs:			dc.l 0
var_runpasses_p:			dc.w 0
for8_l:			dc.w 0
p_sieve_rs:			dc.l 0
var_sieve_i:			dc.w 0
var_sieve_j:			dc.w 0
tmp0:			dc.w 0
tmp1:			dc.w 0
			dc.b 40			; capacity
stmp0:			ds.b 41
			even
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
			dc.b 40					; ntc_inbuf's capacity (as every string variable has)
ntc_inbuf:	ds.b 41					; inputint: typed text
			even
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_f		equ ntc_bss + 0		; 8001 bytes
ntc_bss_size	equ 8002
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
